INSERT INTO knowledge (id, course_id, name, summary, content, route, sort_no, difficulty, tags) VALUES

(113,18,'词法分析','词法分析把字符流切成记号流：用正则表达式描述单词模式，转成 NFA 再确定化为 DFA 并最小化，即可高效扫描源程序。',
'## 核心概念\n编译的第一阶段是**词法分析**：读入字符流，输出**记号（token）流**，同时过滤空白与注释、记录行列号供报错使用。\n\n三个核心概念：\n\n- **模式（pattern）**：一类单词的描述规则，如「标识符 = 字母开头的字母数字串」；\n- **记号（token）**：<种别码, 属性值> 二元组，如 <ID, "count">、<NUM, 42>；\n- **单词（lexeme）**：源程序中实际匹配到的字符串。\n\n**正则表达式**是描述单词模式的标准工具，运算有：连接、选择 `|`、闭包 `*`（0 次或多次）、正闭包 `+`、可选 `?`。识别引擎的实现路线是：\n\n```\n正则表达式  →(Thompson 构造)→  NFA  →(子集构造)→  DFA  →(划分法最小化)→  最小 DFA\n```\n\n- **NFA** 允许同一输入到达多个状态、允许 ε 空转移，构造容易但模拟时要维护状态集合；\n- **DFA** 每个状态对同一输入只有唯一后继，模拟是 O(n)，但状态数可能指数级膨胀（实践中通常可控）；\n- **最小化**用划分法：先按终态/非终态粗分，再反复按「转移后落在哪个组」细分，直到不再变化。\n\n实现时还要处理两个工程细节：**最长匹配原则**（`<=` 应识别为一个记号而不是 `<` 加 `=`）与**关键字优先**（保留字与标识符模式重叠时优先匹配保留字）。\n\n## 代码示例\n\n示例一：正则表达式与记号示例。\n\n```\n常见单词的正则表达式：\n  标识符   letter (letter | digit)*\n  整数字面量  digit digit*\n  无符号浮点数  digit digit* ( . digit digit* )? ( E (+|-)? digit digit* )?\n  注释     // 任意字符* 换行\n\n源程序片段：\n  if (count <= 10) sum += x1;\n\n切分结果：\n  <IF,     \"if\">\n  <LPAREN, \"(\">\n  <ID,     \"count\">\n  <LE,     \"<=\">        ← 最长匹配：不是 < 后接 =\n  <NUM,    10>\n  <RPAREN, \")\">\n  <ID,     \"sum\">\n  <PLUSEQ, \"+=\">\n  <ID,     \"x1\">\n  <SEMI,   \";\">\n```\n\n示例二：从正则到 DFA（子集构造的直观过程）。\n\n```\n正则：(a|b)*abb\n\nThompson 构造得到 NFA 后，用子集构造生成 DFA：\n\n  起始状态集合：{0,1,2,4,7}   （含从 0 出发经 ε 能到的所有状态）\n  读 a → {1,2,3,4,6,7,8}\n  读 b → {1,2,4,5,6,7}\n  ...\n\n把每个「NFA 状态集合」当成一个 DFA 状态，逐个输入符号求转移，\n直到不再出现新的集合。最终含 abb 终态的状态集合即为接受状态。\n\n最小化后通常只剩 4 个状态，对应：\n  「还没见到 a」「见到 a」「见到 ab」「见到 abb(接受)」\n```\n\n## 易错点\n1. 现象：`<=` 被切成 `<` 和 `=`，后续语法分析报错。→ 原因：没用最长匹配。→ 正确写法：扫描器要读到无法继续扩展时才回退输出最长记号。\n2. 现象：`if` 被当成普通标识符。→ 原因：关键字与标识符模式优先级未处理。→ 正确写法：先查关键字表，命中则输出关键字记号。\n3. 现象：正则 `a|b*` 被误解为 `(a|b)*`。→ 原因：闭包优先级高于选择。→ 正确写法：需要分组时显式加括号。\n4. 现象：DFA 模拟时反复回溯，性能很差。→ 原因：用 NFA 直接模拟而未确定化。→ 正确写法：预先确定化为 DFA，模拟才是线性时间。\n5. 现象：报错位置差了一行。→ 原因：扫描器没维护行列计数。→ 正确写法：遇到换行时行号加一、列号归零。\n\n## 考点提示\n1. 正则表达式与三种运算（连接、选择、闭包）。\n2. NFA 与 DFA 的区别及子集构造法（期末必考）。\n3. DFA 最小化的划分法步骤。\n4. 最长匹配原则与关键字优先策略。\n5. 词法分析器的输出形式与在编译流水线中的位置。\n\n## 教材对照\n对应机械工业出版社《编译原理》第 3 章「词法分析」：词法分析器的作用、记号与模式、正则表达式、状态转换图与有限自动机的构造与最小化。',
NULL,1,4,'词法分析,正则表达式,NFA,DFA,子集构造'),

(114,18,'语法分析与 LL/LR','语法分析按文法把记号流组织成语法树：LL 自顶向下做最左推导，LR 自底向上做最右推导的逆过程，LR 能力更强。',
'## 核心概念\n**上下文无关文法（CFG）**由四元组 (终结符, 非终结符, 产生式, 开始符号) 构成。语法分析的任务是：给定文法 G 与记号流，判断该串是否属于 L(G)，是则构造语法树。\n\n两大流派：\n\n| | 自顶向下（LL） | 自底向上（LR） |\n|---|---|---|\n| 推导方向 | 从开始符号推出句子（最左推导） | 从句子归约回开始符号 |\n| 动作 | 展开非终结符 | 移进 / 归约 |\n| 代表 | 递归下降、LL(1) 预测分析表 | LR(0)、SLR、LALR、LR(1) |\n| 能力 | 较弱，需消除左递归与提取左公因子 | 更强，能处理绝大多数程序设计语言文法 |\n\n**LL(1)** 第一个 L 表示从左到右扫描，第二个 L 表示最左推导，1 表示**向前看一个记号**即可确定用哪条产生式。构造预测分析表需要 FIRST 集（某非终结符能推出的首个终结符集合，可能含 ε）与 FOLLOW 集（某非终结符后面可能紧跟的终结符集合）。LL(1) 文法的充要条件是：对同一非终结符的任意两条产生式，其 SELECT 集不相交。\n\n两条必须掌握的文法改造：\n\n- **消除左递归**：`A → Aα | β` 改写为 `A → βA\'`，`A\' → αA\' | ε`；\n- **提取左公因子**：`A → αβ | αγ` 改写为 `A → αA\'`，`A\' → β | γ`。\n\n**LR** 的核心是「句柄」——某产生式右部的一次最左归约。LR 分析表的动作有移进（shift）、归约（reduce）、接受（acc）、报错。冲突分两类：**移进-归约冲突**与**归约-归约冲突**。LALR 是 LR(1) 的状态合并版（同心集合并），状态数大幅减少，是 Yacc/Bison 的默认选择。\n\n## 代码示例\n\n示例一：消除左递归与提取左公因子。\n\n```\n【消除直接左递归】\n  原文法：E → E + T | T\n  改写后：E  → T E\'\n          E\' → + T E\' | ε\n\n【消除间接左递归】先把非终结符排序，逐个代入后再消直接左递归\n\n【提取左公因子】\n  原文法：S → if E then S | if E then S else S\n  改写后：S  → if E then S S\'\n          S\' → else S | ε\n\n改造前后的语言完全等价，但只有改造后的文法才可能是 LL(1)。\n```\n\n示例二：FIRST / FOLLOW 与 LL(1) 表。\n\n```\n文法：\n  E  → T E\'\n  E\' → + T E\' | ε\n  T  → id\n\nFIRST(T)  = { id }\nFIRST(E\') = { +, ε }\nFOLLOW(E\') = { $ }          （E\' 在 E 的最右，继承 FOLLOW(E)）\n\n预测分析表 M：\n           id        +        $\n  E       E→TE\'      —        —\n  E\'      —       E\'→+TE\'   E\'→ε\n  T       T→id       —        —\n\n每个格子最多一个产生式 → 是 LL(1) 文法。\n输入 id + id $ 的分析过程：\n  栈$E   读 id  → E→TE\'\n  栈$E\'T 读 id  → T→id\n  栈$E\'  读 +   → E\'→+TE\'\n  ...\n  栈$    读 $   → acc\n```\n\n## 易错点\n1. 现象：递归下降分析器对左递归文法无限递归爆栈。→ 原因：左递归会让同一个非终结符反复展开。→ 正确写法：先消除左递归。\n2. 现象：LL(1) 表某格有多个产生式。→ 原因：存在左公因子或文法本身有二义性。→ 正确写法：提取左公因子，或改用 LR。\n3. 现象：算 FIRST 时忘了 ε 可传递。→ 原因：若 A→B 且 B 能推出 ε，则 ε ∈ FIRST(A)。→ 正确写法：按不动点迭代计算直到不再变化。\n4. 现象：FOLLOW 算少了导致 SELECT 集偏小。→ 原因：没考虑产生式右部末尾非终结符要继承左部的 FOLLOW。→ 正确写法：按三条规则迭代到不动点。\n5. 现象：以为 LR 一定能处理任何文法。→ 原因：二义文法（如未规定优先级的表达式文法）仍会产生冲突。→ 正确写法：改写文法或显式声明优先级与结合性。\n\n## 考点提示\n1. 给定文法消除左递归、提取左公因子（期末必考）。\n2. FIRST 与 FOLLOW 集的计算。\n3. LL(1) 文法的判定与预测分析表构造。\n4. LR 分析的四种动作与两类冲突。\n5. LL 与 LR 在能力与实现方式上的对比。\n\n## 教材对照\n对应机械工业出版社《编译原理》第 4 章「语法分析」：上下文无关文法、自顶向下分析（递归下降与 LL(1)）、自底向上分析（LR(0)/SLR/LALR/LR(1)）与二义文法的处理。',
NULL,2,5,'语法分析,LL(1),LR,左递归,FIRST/FOLLOW'),

(115,18,'语法制导翻译与中间代码','语法制导翻译把语义动作挂在文法产生式上，边分析边生成代码；中间代码常用三地址码，独立于具体机器便于优化与移植。',
'## 核心概念\n语法分析只回答「句子合不合法」，**语义分析**要回答「句子是什么意思」，并把意思表达成可进一步优化的形式——这就是**语法制导翻译（SDT）**：把语义动作（花括号里的代码）挂在产生式上，分析到该产生式时执行。\n\n两种实现方式：\n\n- **语法制导定义（SDD）**：为文法符号关联属性，分**综合属性**（自底向上，由子结点计算）与**继承属性**（自顶向下，由父结点或兄弟传入）；若只含综合属性称 **S-属性**，可在 LR 分析时随归约计算；若继承属性的依赖不形成环称 **L-属性**，可在 LL 分析时计算。\n- **翻译方案（SDT）**：把动作直接嵌入产生式右部的指定位置。\n\n**中间代码**是源语言与目标机器之间的桥梁，常见形式：\n\n| 形式 | 示例 | 特点 |\n|---|---|---|\n| 三地址码 | `t1 = b * c` | 每条最多一个运算符，最常用 |\n| 四元式 | `(*, b, c, t1)` | op, arg1, arg2, result |\n| 三元式 | `(0) (*, b, c)` | 用编号引用结果 |\n| 逆波兰（后缀） | `b c *` | 无括号，适合栈式求值 |\n| 抽象语法树 / DAG | 树形结构 | DAG 可复用公共子表达式 |\n\n用 **DAG** 表示表达式能天然识别公共子表达式：`a*(b+c) − (b+c)/d` 中 `b+c` 只算一次。\n\n**符号表**贯穿语义分析：记录标识符的类型、作用域、存储位置，支持嵌套作用域的**分程序结构**（进入块时建新表并入栈，离开时出栈）。\n\n## 代码示例\n\n示例一：表达式的语法制导翻译。\n\n```\n文法与语义动作（S-属性，随归约计算）：\n\n  E → E1 + T   { E.code = E1.code || T.code || gen(\"t\"||newtemp()||\" = \"||E1.place||\" + \"||T.place);\n                 E.place = 最新临时变量 }\n  E → T        { E.place = T.place }\n  T → id       { T.place = lookup(id.lexeme).name }\n\n输入：a = b + c * d\n\n生成的三地址码：\n  t1 = c * d\n  t2 = b + t1\n  a  = t2\n\n注意运算符优先级由文法层次（E → T → F）自然保证：\n  越靠近开始符号的运算符优先级越低，故 * 先于 + 被归约。\n```\n\n示例二：四元式与 DAG。\n\n```\n源表达式：a * (b + c) - (b + c) / d\n\n三地址码：\n  t1 = b + c\n  t2 = a * t1\n  t3 = b + c        ← 公共子表达式，可复用 t1\n  t4 = t3 / d\n  t5 = t2 - t4\n\n用 DAG 表示时 (b+c) 只对应一个结点：\n      t5(-)\n     /    \\\n   t2(*)  t4(/)\n   /  \\    /  \\\n  a  t1  t1    d\n        /  \\\n       b    c\n\n公共子表达式被自动共享，这正是 DAG 相对语法树的优势。\n\n布尔表达式与控制流常用回填（backpatching）：\n  if (a < b) goto L1 中的 L1 在生成时还未知，\n  先记下待填位置，等目标标号确定后再统一回填。\n```\n\n## 易错点\n1. 现象：继承属性在自底向上分析时算不出来。→ 原因：继承属性依赖父结点信息，归约时还不可得。→ 正确写法：改写文法消除继承属性，或改用 L-属性方案配合 LL 分析。\n2. 现象：生成的表达式代码运算顺序错了。→ 原因：文法层次没有体现优先级。→ 正确写法：按优先级分层（expr → term → factor）。\n3. 现象：中间代码里临时变量编号重复或错乱。→ 原因：newtemp() 的计数器作用域不对。→ 正确写法：用全局单调递增计数器。\n4. 现象：嵌套作用域里同名变量取到了外层的。→ 原因：符号表查找没从最内层开始。→ 正确写法：按作用域栈由内向外查。\n5. 现象：短路求值被翻译成了两边都计算。→ 原因：布尔表达式直接按算术表达式翻译。→ 正确写法：用跳转代码配合回填实现短路。\n\n## 考点提示\n1. 综合属性与继承属性的区别（期末必考）。\n2. S-属性与 L-属性各自适合哪种分析方式。\n3. 三地址码、四元式、三元式、逆波兰式的写法与转换。\n4. 用 DAG 识别公共子表达式。\n5. 布尔表达式与控制流语句的回填技术。\n\n## 教材对照\n对应机械工业出版社《编译原理》第 5 章「语法制导翻译」与第 6 章「中间代码生成」：语法制导定义与翻译方案、属性计算、三地址码与四元式、声明语句与赋值语句的翻译、布尔表达式与控制流的回填。',
NULL,3,5,'语法制导翻译,三地址码,四元式,DAG,符号表'),

(116,18,'代码优化','优化在不改变程序语义的前提下改进代码：局部优化在基本块内做公共子表达式删除与常量传播，全局优化跨基本块，循环优化外提不变式。',
'## 核心概念\n优化的前提是**不改变程序的语义**（可观测行为等价）。按作用范围分三层：\n\n1. **局部优化**：只在**基本块**内进行。基本块是一段顺序执行、只有一个入口一个出口的代码。手段有：\n   - **公共子表达式删除**：`t1=b+c; t2=b+c` → 复用 t1；\n   - **常量合并（常量折叠）**：`t=2*3.14` 直接算成 `t=6.28`；\n   - **复写传播**：`x=y` 之后把用到 x 的地方换成 y，若 x 此后无用则删除该赋值；\n   - **死代码删除**：计算结果从未被引用的语句直接删掉。\n2. **全局优化**：跨基本块，沿**流图**做数据流分析。核心概念是**到达定值**（某变量的哪些赋值能到达程序某点）与**活跃变量**（某点的变量值以后还会不会被用）。据此可做全局常量传播、全局公共子表达式删除。\n3. **循环优化**：循环是热点，收益最大。手段有：\n   - **代码外提**：把循环内值不变的计算（`t = a * b`，a、b 在循环内不变）提到循环外；\n   - **强度削弱**：把循环里的乘法换成加法（数组元素地址 `base + i*4` 每次迭代只加 4）；\n   - **归纳变量删除**：若两个归纳变量线性相关，删掉多余的那个。\n\n优化不可做的典型反例：不能跨越可能别名（指针）的写操作做常量传播，不能删除可能有副作用的语句（函数调用、volatile 访问）。\n\n## 代码示例\n\n示例一：基本块内的优化。\n\n```\n优化前：\n  t1 = 2 * 3.14        ← 常量合并 → t1 = 6.28\n  t2 = b + c\n  t3 = b + c           ← 公共子表达式 → t3 = t2\n  x  = t2              ← 复写传播：后面用 x 的地方换成 t2\n  y  = x + 1           → y = t2 + 1\n  z  = x * 2           → z = t2 * 2    （此后 x 无用，删除 x = t2）\n  w  = 5               ← 死代码（w 未被使用）→ 删除\n\n优化后：\n  t1 = 6.28\n  t2 = b + c\n  y  = t2 + 1\n  z  = t2 * 2\n```\n\n示例二：循环优化。\n\n```\n优化前：\n  for (i = 0; i < n; i++) {\n      t = a * b;             ← 循环不变，可外提\n      A[i] = (base + i * 4) + t;   ← i*4 可用加法递推（强度削弱）\n  }\n\n代码外提后：\n  t = a * b;\n  for (i = 0; i < n; i++)\n      A[i] = (base + i * 4) + t;\n\n强度削弱 + 归纳变量删除后：\n  t = a * b;\n  p = base;               ← p 取代 base + i*4\n  for (i = 0; i < n; i++) {\n      A[i] = p + t;\n      p = p + 4;          ← 乘法变成加法\n  }\n\n注意：若循环体内存在对 a 或 b 的赋值，t = a*b 就不是\n循环不变量，不能外提 —— 外提前必须做数据流分析确认。\n```\n\n## 易错点\n1. 现象：常量传播后程序在多线程下行为变了。→ 原因：忽略了共享变量可能被其他线程写。→ 正确写法：对 volatile / 原子变量不做跨语句优化。\n2. 现象：认为两个指针一定指向不同内存而做了优化，结果出错。→ 原因：指针别名。→ 正确写法：做别名分析，不确定就保守处理。\n3. 现象：循环不变式外提后反而更慢。→ 原因：外提的代码在循环不执行时也被执行了。→ 正确写法：对可能零次执行的循环放在前置块中。\n4. 现象：删掉了「看起来没用」的函数调用后程序功能缺失。→ 原因：函数有副作用（打印、写文件）。→ 正确写法：只删除已知无副作用且结果未被引用的代码。\n5. 现象：优化后浮点结果与原程序有细微差异。→ 原因：浮点运算不满足结合律，重排会改变舍入。→ 正确写法：默认不做破坏精度的浮点重排，除非开启 fast-math。\n\n## 考点提示\n1. 基本块的划分与流图的构造（期末必考）。\n2. 局部优化四种手段的具体效果。\n3. 循环优化三件套：代码外提、强度削弱、归纳变量删除。\n4. 到达定值与活跃变量的含义。\n5. 优化必须保持语义等价，以及别名与副作用的限制。\n\n## 教材对照\n对应机械工业出版社《编译原理》第 9 章「代码优化」：基本块与流图、局部优化、数据流分析（到达定值与活跃变量）、循环优化与全局优化。',
NULL,4,5,'代码优化,基本块,公共子表达式,代码外提,数据流分析'),

(117,18,'目标代码生成与运行时存储','目标代码生成把中间代码映射到具体指令：关键是寄存器分配与指令选择；运行时靠栈帧组织活动记录，支持函数调用与递归。',
'## 核心概念\n编译的最后阶段是**目标代码生成**：把与机器无关的中间代码映射到具体指令集，主要解决三件事：\n\n1. **指令选择**：用哪条指令实现某个三地址操作（`t = a + b` 可用 `LOAD/ADD/STORE` 三址指令，也可用两址指令）；\n2. **寄存器分配**：寄存器远快于内存，但数量有限。经典做法是**图着色**：为每个待分配值建结点，若两个值在某点同时活跃就连一条边，然后用 k 种颜色（k 个寄存器）给图着色，冲突的值分到不同寄存器。颜色不够时**溢出（spill）**到内存；\n3. **指令调度**：重排指令以填满流水线、避开数据相关造成的停顿。\n\n**运行时存储组织**：程序在内存的典型布局从低地址到高地址为 代码区 → 静态数据区 → 堆（向高地址增长）→ 栈（向低地址增长）。函数调用靠**活动记录（栈帧）**，通常包含：实参、返回地址、控制链（指向调用者的帧）、访问链（嵌套作用域用）、局部数据、临时变量。\n\n调用序列：调用者把实参入栈并保存寄存器 → `CALL` 压入返回地址 → 被调者保存返回地址与控制链、分配局部变量 → 执行 → 被调者恢复寄存器并 `RETURN`。栈帧的创建与销毁是递归能够工作的根本原因——每一层递归有自己独立的一份局部变量。\n\n**静态链 / 显示表（display）** 解决非局部名字的访问：Pascal 这类允许嵌套过程的语言，内层过程要能访问外层过程的局部变量，靠访问链逐层向外找。\n\n## 代码示例\n\n示例一：三地址码到目标代码。\n\n```\n三地址码：\n  t1 = a + b\n  t2 = t1 * c\n  d  = t2\n\n朴素目标代码（三址指令，寄存器充足）：\n  LOAD  R1, a        ; R1 = a\n  ADD   R1, R1, b    ; R1 = a + b\n  MUL   R1, R1, c    ; R1 = (a+b) * c\n  STORE d, R1        ; d = R1\n\n若只有两个寄存器且 a、b、c 都在内存：\n  LOAD  R1, a\n  ADD   R1, b\n  LOAD  R2, c\n  MUL   R1, R2\n  STORE d, R1\n\n寄存器不够时的溢出：\n  STORE t1, R1       ; 把 t1 暂时写回内存腾出寄存器\n  ...\n  LOAD  R1, t1       ; 需要时再取回\n```\n\n示例二：栈帧布局与递归。\n\n```\n典型栈帧（从高地址往低）：\n  +------------------+\n  | 实参 n ... 实参 1 |\n  | 返回地址          |\n  | 控制链(老 fp)     |   ← 当前 fp 指向这里\n  | 局部变量          |\n  | 临时变量          |\n  +------------------+   ← sp 指向栈顶\n\n递归求阶乘 fact(3) 执行到最深处的栈：\n  fact(1) 的帧  (n=1)\n  fact(2) 的帧  (n=2)\n  fact(3) 的帧  (n=3)\n  main    的帧\n\n每层 n 是各自帧里的独立副本，故递归不会互相干扰；\n返回时逐层弹出并把返回值传给下一层。\n栈空间有限，递归过深会造成栈溢出（stack overflow）。\n```\n\n## 易错点\n1. 现象：生成的代码把还在用的值覆盖了。→ 原因：寄存器分配时没正确计算活跃区间。→ 正确写法：先做活跃变量分析再分配，冲突的值不能共用寄存器。\n2. 现象：图着色失败导致生成不了代码。→ 原因：寄存器数少于图的色数。→ 正确写法：选择溢出代价最小的值写回内存。\n3. 现象：函数返回后局部变量的值变成乱码。→ 原因：返回了指向已释放栈帧的指针。→ 正确写法：不要返回局部变量的地址。\n4. 现象：内层过程访问不到外层变量。→ 原因：未维护访问链或显示表。→ 正确写法：建立静态链并在调用时正确设置。\n5. 现象：递归深度稍大就崩溃。→ 原因：栈空间耗尽。→ 正确写法：改为迭代，或使用尾递归优化（把尾调用转成跳转复用同一帧）。\n\n## 考点提示\n1. 代码生成器的三个主要任务：指令选择、寄存器分配、指令调度（期末必考）。\n2. 图着色寄存器分配的基本思想与溢出处理。\n3. 活动记录（栈帧）各字段的作用。\n4. 调用序列与返回序列各步骤。\n5. 静态链 / 显示表解决非局部访问的原理。\n\n## 教材对照\n对应机械工业出版社《编译原理》第 8 章「代码生成」与第 7 章「运行时刻环境」：目标代码生成的基本问题、寄存器分配与图着色、存储组织与栈式分配、活动记录与非局部名字的访问。',
NULL,5,5,'目标代码生成,寄存器分配,图着色,活动记录,栈帧')
ON DUPLICATE KEY UPDATE name=VALUES(name), summary=VALUES(summary), content=VALUES(content), route=VALUES(route), sort_no=VALUES(sort_no), difficulty=VALUES(difficulty), tags=VALUES(tags);

-- ---------- 习题：编译原理（113-117，每题 3 道） ----------
INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, score) VALUES

-- ---------- 113 词法分析 ----------
(113,'期末',3,'single','词法分析器的输出是？',
 '[{"key":"A","text":"语法树"},{"key":"B","text":"记号（token）流"},{"key":"C","text":"目标代码"},{"key":"D","text":"中间代码"}]',
 'B','词法分析读入字符流，按模式切分并输出 <种别码, 属性值> 形式的记号流，同时过滤空白与注释、记录行列号。语法树由后续的语法分析产生，中间代码由语义分析与中间代码生成阶段产生，目标代码由最后的代码生成阶段产生。',5),
(113,'期末',4,'single','扫描源程序时遇到 "<="，正确的处理方式是？',
 '[{"key":"A","text":"输出 < 和 = 两个记号"},{"key":"B","text":"按最长匹配原则输出一个 <= 记号"},{"key":"C","text":"报错"},{"key":"D","text":"当作标识符处理"}]',
 'B','词法分析遵循最长匹配原则：扫描器应尽可能多地读入能构成合法记号的字符，直到再读一个就无法构成任何记号时才回退并输出当前最长的记号。因此 "<=" 必须识别为单个关系运算符记号，否则语法分析会因记号序列不符而报错。',5),
(113,'软考',3,'judge','判断下列说法是否正确：NFA 与 DFA 的识别能力等价，任何 NFA 都可以通过子集构造法转换为等价的 DFA，代价是状态数可能指数级增长。',
 '[]','T','正确。两者都恰好识别正则语言，能力相同。子集构造把每个「NFA 状态集合」当作一个 DFA 状态，从而消除不确定性；理论上状态数可达 2^n，但实践中绝大多数词法模式膨胀可控。转换为 DFA 后模拟是线性时间，不必维护状态集合。',3),

-- ---------- 114 语法分析与 LL/LR ----------
(114,'期末',3,'single','文法 E → E + T | T 存在左递归，消除后应改写为？',
 '[{"key":"A","text":"E → T E1，E1 → + T E1 | ε"},{"key":"B","text":"E → T + E | T"},{"key":"C","text":"E → + T E"},{"key":"D","text":"E → T | + T"}]',
 'A','消除直接左递归 A → Aα | β 的标准改法是 A → βA1，A1 → αA1 | ε，把左递归变成右递归。本例中 α = "+ T"、β = "T"，故得 E → T E1，E1 → + T E1 | ε。这样做是为了让自顶向下分析能在读入有限个记号后确定用哪条产生式，否则会无限递归。',5),
(114,'考研408',4,'single','关于 LL(1) 文法，下列说法正确的是？',
 '[{"key":"A","text":"LL(1) 的含义是从右向左扫描、最右推导、向前看一个符号"},{"key":"B","text":"LL(1) 文法要求同一非终结符的各产生式 SELECT 集互不相交"},{"key":"C","text":"LL(1) 能处理所有上下文无关文法"},{"key":"D","text":"LL(1) 分析能力强于 LR(1)"}]',
 'B','LL(1) 指从左到右扫描、最左推导、向前看一个记号。其判定条件是：对同一非终结符的任意两条产生式，SELECT 集不相交，这样预测分析表每格最多一个产生式。A 把方向说反；C 错，LL(1) 只能处理文法的一个真子集；D 错，LR 族的识别能力强于 LL。',5),
(114,'期末',3,'judge','判断下列说法是否正确：LR 分析中的「移进-归约冲突」指在某状态下既可把下一记号移进栈、又可按某产生式归约，仅凭当前状态与向前看记号无法唯一确定动作。',
 '[]','T','正确。LR 分析的动作由状态与向前看记号共同决定；若表中同一格同时出现移进与归约（或两个不同的归约，即归约-归约冲突），该文法就不是对应 LR 类的文法。解决办法包括改写文法、声明运算符优先级与结合性（Yacc 的机制），或升级到更强的 LR(1)。',3),

-- ---------- 115 语法制导翻译与中间代码 ----------
(115,'期末',3,'single','四元式 ( *, b, c, t1 ) 表示的运算是？',
 '[{"key":"A","text":"t1 = b * c"},{"key":"B","text":"b = c * t1"},{"key":"C","text":"c = b * t1"},{"key":"D","text":"* = b * c"}]',
 'A','四元式的四个字段依次是 (op, arg1, arg2, result)，表示把 arg1 与 arg2 按 op 运算的结果存入 result。因此 ( *, b, c, t1 ) 即 t1 = b * c。四元式是三地址码的一种具体表示，便于后续做优化与生成目标代码。',5),
(115,'期末',3,'single','关于综合属性与继承属性，下列说法正确的是？',
 '[{"key":"A","text":"综合属性由父结点或兄弟结点传入，继承属性由子结点计算"},{"key":"B","text":"综合属性自底向上由子结点计算，继承属性自顶向下由父结点或兄弟传入"},{"key":"C","text":"两者完全相同"},{"key":"D","text":"综合属性只能用于 LR，继承属性只能用于 LL"}]',
 'B','综合属性的值由该结点子结点的属性计算而来，天然适合在自底向上（LR）归约时计算；继承属性的值由父结点或左兄弟传入，用于把上下文信息向下传递。B 的表述正确；A 把两者说反；D 的说法过于绝对，L-属性文法也可在 LL 分析中计算。',5),
(115,'期末',4,'judge','判断下列说法是否正确：用有向无环图（DAG）而不是语法树表示表达式，可以天然识别并复用公共子表达式，从而避免重复计算。',
 '[]','T','正确。DAG 允许多个父结点共享同一个子结点，因此表达式中重复出现的子表达式（如 a*(b+c) − (b+c)/d 中的 b+c）只会生成一个结点，后续优化时可复用已算出的临时变量。语法树不允许共享，同一子表达式会出现多份。',3),

-- ---------- 116 代码优化 ----------
(116,'期末',3,'single','下列优化中，属于循环优化的是？',
 '[{"key":"A","text":"常量合并"},{"key":"B","text":"代码外提（把循环不变量移到循环外）"},{"key":"C","text":"死代码删除"},{"key":"D","text":"复写传播"}]',
 'B','循环优化针对循环体内的热点代码，三件套是代码外提、强度削弱与归纳变量删除。代码外提把循环内值不变的计算移出循环，是收益最明显的手段。常量合并、死代码删除、复写传播属于基本块内的局部优化，不依赖循环结构。',5),
(116,'期末',3,'single','基本块的特点是？',
 '[{"key":"A","text":"包含任意数量的入口和出口"},{"key":"B","text":"顺序执行、只有一个入口和一个出口的一段代码"},{"key":"C","text":"必须包含循环"},{"key":"D","text":"必须包含函数调用"}]',
 'B','基本块是从第一条语句进入、到最后一条语句离开的一段顺序代码，中间没有跳转进入也没有跳转出去（除最后一条）。划分方法是找出首指令（程序第一条、跳转目标、跳转后的指令），每个首指令到下一个首指令之前构成一个基本块。基本块是局部优化的基本单位。',5),
(116,'期末',4,'judge','判断下列说法是否正确：优化的前提是保持程序语义等价，因此对于可能有副作用的函数调用、volatile 变量访问以及存在指针别名的情形，编译器必须保守处理而不能随意删除或重排。',
 '[]','T','正确。优化只允许改变不可观测的实现细节。函数调用可能打印或修改全局状态、volatile 访问对应外部可见副作用、指针别名使得「两个变量是否同一内存」无法确定，这些情形下激进的常量传播与死代码删除都会改变程序行为，必须放弃优化以保证正确性。',3),

-- ---------- 117 目标代码生成与运行时存储 ----------
(117,'期末',3,'single','寄存器分配常用的图着色方法中，「溢出（spill）」指的是？',
 '[{"key":"A","text":"寄存器数量不足时，把某些值暂存到内存"},{"key":"B","text":"寄存器内容丢失"},{"key":"C","text":"删除无用变量"},{"key":"D","text":"把指令排到流水线上"}]',
 'A','图着色把每个待分配值建成结点，同时活跃的值之间连边，用 k 种颜色（k 个寄存器）着色。当图的色数大于可用寄存器数时，无法完成着色，就必须把部分值写回内存并在需要时重新载入，这称为溢出。选择溢出对象时通常挑访问频率最低、溢出代价最小的那个。',5),
(117,'期末',3,'single','函数调用时，活动记录（栈帧）中通常不包含？',
 '[{"key":"A","text":"实参"},{"key":"B","text":"返回地址"},{"key":"C","text":"全局变量的值"},{"key":"D","text":"局部变量"}]',
 'C','活动记录是为一次函数调用临时分配的栈空间，包含实参、返回地址、控制链（指向调用者帧）、局部变量与临时变量。全局变量存放在静态数据区，生命周期贯穿整个程序，不属于任何单个活动的栈帧。',5),
(117,'期末',3,'judge','判断下列说法是否正确：递归能够正常工作，是因为每次调用都会在栈上创建独立的活动记录，各层递归的局部变量互不干扰；但栈空间有限，递归过深会导致栈溢出。',
 '[]','T','正确。每次函数调用都在栈顶压入一个新的活动记录，保存该次调用的实参与局部变量，因此同一函数的多次活跃调用各有一份独立的存储。返回时栈帧弹出。由于栈的容量有限且由系统预设，缺少递归出口或深度过大就会耗尽栈空间，产生栈溢出。',3);
